<?php
return function (PDO $db): void {
    $db->exec("CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190), slug VARCHAR(190) UNIQUE, reference VARCHAR(80) UNIQUE, description TEXT, price DECIMAL(12,2) NULL, stock_status ENUM('in_stock','on_order','out_of_stock') DEFAULT 'in_stock', stock_quantity INT DEFAULT 0, lead_time VARCHAR(100) NULL, image VARCHAR(255) NULL, status ENUM('draft','published','archived') DEFAULT 'draft', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $db->exec("CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, reference VARCHAR(40) UNIQUE, status ENUM('pending','paid','processing','shipping','completed','cancelled') DEFAULT 'pending', payment_method VARCHAR(50) NULL, payment_status ENUM('pending','paid','failed','refunded','cod') DEFAULT 'pending', delivery_method ENUM('pickup','delivery') DEFAULT 'pickup', delivery_zone VARCHAR(100) NULL, subtotal DECIMAL(12,2), delivery_fee DECIMAL(12,2) DEFAULT 0, total DECIMAL(12,2), customer_data JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $db->exec("CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED, item_type ENUM('course','product'), item_id BIGINT UNSIGNED, label VARCHAR(190), quantity INT UNSIGNED DEFAULT 1, unit_price DECIMAL(12,2), total DECIMAL(12,2), FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $db->exec("CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED, provider VARCHAR(50), provider_reference VARCHAR(190) NULL, amount DECIMAL(12,2), status ENUM('initiated','pending','successful','failed','refunded') DEFAULT 'initiated', payload JSON NULL, paid_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $db->exec("CREATE TABLE certificates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED, course_id BIGINT UNSIGNED, reference VARCHAR(80) UNIQUE, file_path VARCHAR(255) NULL, issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
};
